import AVFoundation
import CallKit
import Foundation

/// Native phone-call UX via CallKit: lock-screen ringing, Bluetooth/intercom answer button, Recents.
///
/// Every call has a callId (generated by the phone for calls we place, by the hub for calls it places).
/// Hub messages for any other callId are ignored, so a stale "ended" can never kill the live call.
/// If the WebSocket drops mid-call, the hub keeps the conversation for a grace period and the phone
/// re-attaches with the same callId after reconnecting.
final class CallManager: NSObject, ObservableObject, CXProviderDelegate {
    static let shared = CallManager()

    struct ActiveCall: Equatable {
        let uuid: UUID
        let callId: String
        /// "outbound" = the hub called us, "inbound" = we called the hub (hub's perspective).
        let direction: String
        let createdAt: Date
        var answered = false
        var ready = false
        var connectedAt: Date?
    }

    @Published private(set) var active: ActiveCall? {
        didSet { hub.callActive.value = active != nil }
    }
    @Published var muted = false { didSet { audio.muted = muted } }
    /// Loudspeaker on/off (remembered). Off = earpiece, or the Bluetooth/intercom route when connected.
    @Published var speaker = UserDefaults.standard.bool(forKey: "cmc.speaker") {
        didSet {
            UserDefaults.standard.set(speaker, forKey: "cmc.speaker")
            applySpeaker()
        }
    }
    var hasActiveCall: Bool { active != nil }

    private let provider: CXProvider
    private let controller = CXCallController()
    private let audio = AudioIO()
    private let hub = HubClient.shared
    private let synth = AVSpeechSynthesizer()
    /// Short "task complete" alerts outside calls; its own audio session, so it ducks music and uses the headset.
    private let announcer: AVSpeechSynthesizer = {
        let s = AVSpeechSynthesizer()
        s.usesApplicationAudioSession = false
        return s
    }()
    private let micOn = AtomicFlag()

    override init() {
        let cfg = CXProviderConfiguration()
        cfg.supportsVideo = false
        cfg.maximumCallGroups = 1
        cfg.maximumCallsPerCallGroup = 1
        cfg.supportedHandleTypes = [.generic]
        cfg.includesCallsInRecents = true
        provider = CXProvider(configuration: cfg)
        super.init()
        provider.setDelegate(self, queue: nil)

        audio.onMic = { [weak self] d in
            guard let self, self.micOn.value else { return }
            self.hub.sendAudio(d)
        }
        hub.onAudio = { [weak self] d in self?.audio.play(d) }
        hub.onFlush = { [weak self] in self?.audio.flush() }
        hub.onAnnounce = { [weak self] text, lang in
            DispatchQueue.main.async {
                // Never over a call: Claude is already talking there.
                guard let self, self.active == nil else { return }
                let u = AVSpeechUtterance(string: text)
                u.voice = AVSpeechSynthesisVoice(language: lang) ?? AVSpeechSynthesisVoice(language: "en-US")
                self.announcer.speak(u)
                Log.d("announce: \(text)")
            }
        }
        hub.onIncoming = { [weak self] callId, title in
            DispatchQueue.main.async { self?.reportIncoming(callId: callId, title: title) }
        }
        hub.onCallReady = { [weak self] callId in
            DispatchQueue.main.async {
                guard let self, var a = self.active, a.callId == callId else { return }
                Log.d("call ready \(callId)")
                if !a.ready, a.direction == "inbound" { self.provider.reportOutgoingCall(with: a.uuid, connectedAt: Date()) }
                if !a.ready { a.connectedAt = Date() }
                a.ready = true
                self.active = a
            }
        }
        hub.onCallEnded = { [weak self] callId, reason in
            DispatchQueue.main.async {
                guard let self else { return }
                guard let a = self.active, a.callId == callId else {
                    Log.d("ignoring end for other call \(callId) (\(reason))")
                    return
                }
                Log.d("hub ended call \(callId): \(reason)")
                self.provider.reportCall(with: a.uuid, endedAt: Date(), reason: reason.contains("error") ? .failed : .remoteEnded)
                self.cleanup()
            }
        }
        // WebSocket came back while we are in a call → re-attach to the same conversation.
        hub.onConnected = { [weak self] in
            DispatchQueue.main.async {
                guard let self, let a = self.active, a.answered else { return }
                Log.d("reconnected during call → resume \(a.callId)")
                self.hub.sendJSON(["type": "call.start", "callId": a.callId, "direction": a.direction])
            }
        }
    }

    // MARK: entry points

    /// Hub is calling (VoIP push or socket). Must be reported to CallKit immediately.
    func reportIncoming(callId: String, title: String, completion: (() -> Void)? = nil) {
        let update = CXCallUpdate()
        update.remoteHandle = CXHandle(type: .generic, value: "Claude")
        update.localizedCallerName = title.isEmpty ? "Claude" : "Claude · \(title)"
        update.hasVideo = false
        update.supportsHolding = false
        update.supportsGrouping = false
        update.supportsDTMF = false

        if let a = active {
            if a.callId == callId { completion?(); return } // push + socket both delivered it
            // Busy: iOS still requires reporting every VoIP push, so report and end immediately.
            let u = UUID()
            Log.d("incoming \(callId) while busy with \(a.callId) → declined")
            provider.reportNewIncomingCall(with: u, update: update) { [weak self] _ in
                self?.provider.reportCall(with: u, endedAt: Date(), reason: .unanswered)
                completion?()
            }
            hub.sendJSON(["type": "call.end", "callId": callId])
            return
        }
        let uuid = UUID()
        active = ActiveCall(uuid: uuid, callId: callId, direction: "outbound", createdAt: Date())
        Log.d("incoming call \(callId) '\(title)'")
        provider.reportNewIncomingCall(with: uuid, update: update) { [weak self] error in
            if let error {
                Log.d("reportNewIncomingCall failed: \(error)")
                DispatchQueue.main.async { if self?.active?.uuid == uuid { self?.active = nil } }
            }
            completion?()
        }
        hub.ensureConnected()
    }

    /// Developer calls the hub ("Claude'u ara", Siri, Recents).
    func startOutgoing() {
        if let a = active {
            // Recover from a stuck call that never got answered/connected.
            if !a.ready, Date().timeIntervalSince(a.createdAt) > 20 {
                Log.d("clearing stuck call \(a.callId)")
                provider.reportCall(with: a.uuid, endedAt: Date(), reason: .failed)
                cleanup()
            } else {
                return
            }
        }
        let uuid = UUID()
        let callId = "c_" + UUID().uuidString.prefix(8).lowercased()
        active = ActiveCall(uuid: uuid, callId: callId, direction: "inbound", createdAt: Date())
        Log.d("placing call \(callId)")
        let action = CXStartCallAction(call: uuid, handle: CXHandle(type: .generic, value: "Claude"))
        action.isVideo = false
        controller.request(CXTransaction(action: action)) { [weak self] err in
            if let err {
                Log.d("start call failed: \(err)")
                DispatchQueue.main.async { if self?.active?.uuid == uuid { self?.active = nil } }
            }
        }
    }

    func hangUp() {
        guard let a = active else { return }
        controller.request(CXTransaction(action: CXEndCallAction(call: a.uuid))) { [weak self] err in
            if let err {
                // CallKit no longer knows this call: clean up ourselves so the app is never stuck.
                Log.d("end call request failed: \(err) → local cleanup")
                self?.hub.sendJSON(["type": "call.end", "callId": a.callId])
                self?.cleanup()
            }
        }
    }

    // MARK: CXProviderDelegate

    func providerDidReset(_ provider: CXProvider) {
        Log.d("provider reset")
        cleanup()
    }

    func provider(_ provider: CXProvider, perform action: CXStartCallAction) {
        AudioIO.configureSession()
        provider.reportOutgoingCall(with: action.callUUID, startedConnectingAt: Date())
        action.fulfill()
        beginConversation()
    }

    func provider(_ provider: CXProvider, perform action: CXAnswerCallAction) {
        AudioIO.configureSession()
        action.fulfill()
        beginConversation()
    }

    func provider(_ provider: CXProvider, perform action: CXEndCallAction) {
        if let a = active {
            Log.d("user ended call \(a.callId)")
            hub.sendJSON(["type": "call.end", "callId": a.callId])
        }
        cleanup()
        action.fulfill()
    }

    func provider(_ provider: CXProvider, perform action: CXSetMutedCallAction) {
        DispatchQueue.main.async { self.muted = action.isMuted }
        action.fulfill()
    }

    func provider(_ provider: CXProvider, didActivate audioSession: AVAudioSession) {
        Log.d("audio session activated")
        audio.start()
        applySpeaker()
    }

    func provider(_ provider: CXProvider, didDeactivate audioSession: AVAudioSession) {
        Log.d("audio session deactivated")
        audio.stop()
    }

    // MARK: helpers

    /// Answered / placed: connect (if needed) and tell the hub to start the conversation, exactly once.
    private func beginConversation() {
        DispatchQueue.main.async {
            guard var a = self.active, !a.answered else { return }
            a.answered = true
            self.active = a
            self.micOn.value = true
            let callId = a.callId
            let direction = a.direction
            // Never hang on "connecting…": give up cleanly after 15 s.
            DispatchQueue.main.asyncAfter(deadline: .now() + 15) { [weak self] in
                guard let self, let a = self.active, a.callId == callId, !a.ready else { return }
                Log.d("call \(callId) not ready after 15s")
                self.unreachable()
            }
            self.hub.ensureConnected { [weak self] ok in
                guard let self, self.active?.callId == callId else { return }
                guard ok else { return self.unreachable() }
                Log.d("call.start \(callId) \(direction)")
                // Idempotent on the hub: the same callId re-attaches instead of starting over.
                self.hub.sendJSON(["type": "call.start", "callId": callId, "direction": direction])
            }
        }
    }

    private func applySpeaker() {
        guard active != nil else { return }
        do {
            try AVAudioSession.sharedInstance().overrideOutputAudioPort(speaker ? .speaker : .none)
        } catch {
            Log.d("speaker override failed: \(error)")
        }
    }

    /// Mac unreachable: say so locally, then end the call.
    private func unreachable() {
        Log.d("hub unreachable for call")
        let lang = hub.snapshot?.language ?? "en-US"
        let u = AVSpeechUtterance(string: CallManager.unreachableText(lang))
        u.voice = AVSpeechSynthesisVoice(language: lang) ?? AVSpeechSynthesisVoice(language: "en-US")
        synth.speak(u)
        DispatchQueue.main.asyncAfter(deadline: .now() + 6) { [weak self] in self?.hangUp() }
    }

    /// Spoken locally when the Mac can't be reached, in the configured voice language.
    static func unreachableText(_ lang: String) -> String {
        switch String(lang.prefix(2)) {
        case "tr": return "Mac'ine ulaşılamıyor. Uygulamayı açıp tekrar eşleştirmeyi dene."
        case "de": return "Dein Mac ist nicht erreichbar. Öffne die App und kopple ihn erneut."
        case "fr": return "Ton Mac est injoignable. Ouvre l'app et refais le jumelage."
        case "es": return "No se puede contactar con tu Mac. Abre la app y vuelve a emparejarlo."
        case "it": return "Il tuo Mac non è raggiungibile. Apri l'app e prova ad abbinarlo di nuovo."
        case "pt": return "Não foi possível contactar o teu Mac. Abre a app e emparelha-o de novo."
        default: return "Your Mac can't be reached. Open the app and try pairing again."
        }
    }

    private func cleanup() {
        micOn.value = false
        audio.stop()
        DispatchQueue.main.async {
            self.active = nil
            self.muted = false
        }
    }
}
